+
+	// Stop and verify transition.
+	if _, err := env.client.Stop(ctx, &pb.StopRequest{JobId: id}); err != nil {
+		t.Fatalf("Stop: %v", err)
+	}
+
+	awaitJobExit(t, env, id)
