+	st, err = env.client.GetStatus(ctx, &pb.GetStatusRequest{JobId: id})
+	if err != nil {
+		t.Fatalf("GetStatus after stop: %v", err)
+	}
+	if st.GetStatus() != pb.JobStatus_JOB_STATUS_STOPPED {
+		t.Fatalf("status = %v, want STOPPED", st.GetStatus())
+	}
